INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(24101, 'Luke 7:33', 'Luke', 7, 33, '&nbsp;ځکه چې بپتسمه ورکوونکے يحيىٰ راغلو چې هغۀ نۀ روټۍ خوړله او نۀ يې مے څښل نو تاسو وئيل چې، په هغۀ پيريان ناست دى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24102, 'Luke 7:34', 'Luke', 7, 34, '&nbsp;او کله چې اِبن آدم راغلو چې خورى څښى نو تاسو وايئ چې، دۀ ته وګورئ. دا ګيډور شرابى د محصولچيانو او ګناهګارو دوست دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24103, 'Luke 7:35', 'Luke', 7, 35, '&nbsp;خو بيا هم حکمت په خپلو کارونو کولو صادق ثابت شو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24104, 'Luke 7:36', 'Luke', 7, 36, '&nbsp;يو فريسى د عيسىٰ مېلمستيا وکړله. هغه د فريسى کور ته لاړو او خوراک ته کښېناستو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24105, 'Luke 7:37', 'Luke', 7, 37, '&nbsp;نو په هغه ښار کښې يوه زناکاره ښځه چې د عيسىٰ د راتلو نه خبر شوله چې د يو فريسى په کور کښې مېلمه دے نو قيمتى عطر يې د مرمرو په عطردان کښې راوړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24106, 'Luke 7:38', 'Luke', 7, 38, '&nbsp;هغه د عيسىٰ د پښو سره وروستو ودرېدله او په ژړا شوه او د هغۀ پښې د هغې په اوښکو لمدې شوې او هغه هغې په خپلو وېښتو وچې کړې او ښکل يې کړې او عطر يې پرې واچول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24107, 'Luke 7:39', 'Luke', 7, 39, '&nbsp;کله چې د هغۀ کوربه فريسى دا وليدل نو د ځان سره يې ووئيل، ”کۀ دا سړے چرې رښتينے نبى وے نو هغه به په دې خبر وے چې دا لاس وروړونکې ښځه څوک ده او دا څنګه ښځه ده يعنې يوه ګناهګاره ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24108, 'Luke 7:40', 'Luke', 7, 40, '&nbsp;عيسىٰ د هغۀ په زړۀ پوهه شو او ورته يې وفرمائيل چې، ”شمعونه. زۀ تا ته څۀ وئيل غواړم.“ هغۀ ووئيل چې، ”ووايه مالِکه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24109, 'Luke 7:41', 'Luke', 7, 41, '&nbsp;عيسىٰ ورته وفرمائيل چې، ”د يو سودخور دوه قرضدارى وُو. يو ته يې پينځۀ سوه ديناره قرض وُو او په بل يې پنځوس.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24110, 'Luke 7:42', 'Luke', 7, 42, '&nbsp;د دواړو سره د قرض ورکولو هيڅ درک نۀ وو نو دواړو ته يې وبخښل. نو اوس ووايه چې په دې دواړو کښې به د هغۀ سره زياته مينه کوم يو کوى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24111, 'Luke 7:43', 'Luke', 7, 43, '&nbsp;شمعون جواب ورکړو، ”زما په خيال چې کوم سړى ته يې زياتې وبخښلې.“ عيسىٰ وفرمائيل چې، ”بې‌شکه تۀ صحيح وائې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24112, 'Luke 7:44', 'Luke', 7, 44, '&nbsp;بيا يې ښځې ته مخ ورواړولو او شمعون ته يې وفرمائيل چې، ”تۀ دا ښځه وينې؟ زۀ ستا کور ته راغلم او تا زما د پښو دپاره اوبۀ قدرې هم رانۀ کړې خو دې ښځې زما پښې په خپلو اوښکو لمدې کړې او هغه يې په خپلو وېښتو وچې کړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24113, 'Luke 7:45', 'Luke', 7, 45, '&nbsp;تا زۀ ښکل قدرې نۀ کړم خو د کوم وخت نه چې زۀ راغلے يم هغه لګيا ده زما پښې ښُکلوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24114, 'Luke 7:46', 'Luke', 7, 46, '&nbsp;تا زما سر په تېلو غوړ نۀ کړو او هغې زما په پښو عطر واچول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24115, 'Luke 7:47', 'Luke', 7, 47, '&nbsp;زۀ تا ته دا وايم چې هغې دومره مينه وکړله ځکه چې د هغې ډېر ګناهونه بخښلے شوى دى. د چا چې لږ ګناهونه بخښلے شوى وى هغه لږه مينه کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24116, 'Luke 7:48', 'Luke', 7, 48, '&nbsp;بيا عيسىٰ هغې ته وفرمائيل چې، ”ستا ګناهونه وبخښلے شول.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24117, 'Luke 7:49', 'Luke', 7, 49, '&nbsp;نو مېلمنو په خپلو کښې ووئيل چې، ”دے لا څوک دے چې ګناهونه هم بخښى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24118, 'Luke 7:50', 'Luke', 7, 50, '&nbsp;او بيا عيسىٰ هغې ښځې ته وفرمائيل چې، ”تۀ خپل ايمان بچ کړې، په خير لاړه شه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24119, 'Luke 8:1', 'Luke', 8, 1, '&nbsp;د دې نه پس عيسىٰ ښار په ښار او کلى په کلى ګرځېدو، بيان يې کولو او د خُدائ پاک د بادشاهۍ زيرے يې اورولو. او هغۀ سره هغه دولس مريدان هم وُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24120, 'Luke 8:2', 'Luke', 8, 2, '&nbsp;او يو څو ښځې وې څوک چې د پيريانو نه خلاصې شوې وې او د رنځونو نه جوړې شوې وې. په دوئ کښې مريم چې د مګدلينى په نوم يادېده د چا نه چې اووۀ پيريان شړلے شوى وُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24121, 'Luke 8:3', 'Luke', 8, 3, '&nbsp;او يوانه چې د هيروديس د خُوزا نومې ناظر ښځه وه او سوسناه او نورې ډيرې ښځې چې په خپل مال دولت يې د هغوئ خرچه کوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24122, 'Luke 8:4', 'Luke', 8, 4, '&nbsp;او ډېر خلق د مختلفو ښارونو نه عيسىٰ ته راجمع کېدل نو هغۀ په دې مِثال کښې خبرې وکړې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24123, 'Luke 8:5', 'Luke', 8, 5, '&nbsp;”يو زميندار د تخم کَرلو دپاره بهر لاړو نو چې کله هغۀ په خپل پټى کښې تخم نوستلو نو څۀ تخم ترې نه په لاره پرېوتو او د پښو د لاندې شو او د هوا مارغان راغلل هغه يې وخوړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24124, 'Luke 8:6', 'Luke', 8, 6, '&nbsp;څۀ تخم په کاڼيزه زمکه پرېوتو او څۀ وخت پس زرغون شو او اوچ شو ځکه چې د نمى کمے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24125, 'Luke 8:7', 'Luke', 8, 7, '&nbsp;او څۀ تخم په غنو کښې پرېوتو، ازغى ورسره لوئ شول او فصل يې لاندې کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24126, 'Luke 8:8', 'Luke', 8, 8, '&nbsp;او څۀ تخم په زرخيزه زمکه پرېوتو او راوټوکېدو او لوئ شو يو په سل غله يې وکړه.“ هر کله چې عيسىٰ دا وفرمائيل نو آواز يې وکړو، ”کۀ څوک د اورېدو غوږونه لرى نو هغه دې واورى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24127, 'Luke 8:9', 'Luke', 8, 9, '&nbsp;د هغۀ مريدانو تپوس ترې وکړو چې د دې مِثال مطلب څۀ وو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24128, 'Luke 8:10', 'Luke', 8, 10, '&nbsp;نو هغۀ وفرمائيل چې، ”تاسو ته دا موقع درکړے شوې ده چې د خُدائ پاک د بادشاهۍ په رازونو پوهه شئ، خو زۀ د نورو دپاره په مِثالونو کښې تعليم ورکوم، ”هغوئ ګورى خو وينى نه، اورى خو پوهيږى نه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24129, 'Luke 8:11', 'Luke', 8, 11, '&nbsp;د دې مِثال مطلب دا دے چې تخم د خُدائ پاک کلام دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24130, 'Luke 8:12', 'Luke', 8, 12, '&nbsp;او د لارې په غاړه هغه څوک دى چې څوک دا اورى خو وروستو اِبليس راشى او هغه کلام د هغوئ د زړۀ نه يوسى، هسې نه چې ايمان راوړى او خلاصون بيامومى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24131, 'Luke 8:13', 'Luke', 8, 13, '&nbsp;په کاڼيزه زمکه د کَرلے شوى تخم مِثال د هغه چا دے چې هر کله چې کلام واورى په خوشحالۍ سره يې قبول کړى خو جرړې يې نۀ وى او د لږ وخت دپاره پرې ايمان راوړى نو د آزمېښت په وخت کښې تيندک وخورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24132, 'Luke 8:14', 'Luke', 8, 14, '&nbsp;او په غنو کښې د پرېوتلى تخم مِثال د هغه چا دے څوک چې کلام واورى خو نوره وده يې د مال دولت لالچ او د ژوند د خوشحالو په وجه مرۍ خپه کړى او مېوه يې پخه نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24133, 'Luke 8:15', 'Luke', 8, 15, '&nbsp;خو د ښې زمکې مِثال د هغه چا دے څوک چې په ښۀ او پاک زړۀ سره کلام واورى او پرې مضبوط شى او په دې د صبر مېوه راوړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24134, 'Luke 8:16', 'Luke', 8, 16, '&nbsp;داسې هيڅوک نشته چې ډيوه بله کړى او بيا يې د لوښى د لاندې پټه کړى او يا يې د کټ لاندې کېږدى بلکې هغه يې په ډيوټ ږدى چې هر راتلونکے کس يې رڼا ووينى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24135, 'Luke 8:17', 'Luke', 8, 17, '&nbsp;داسې پټ څيز نشته چې هغه به ښکاره نۀ شى او نۀ داسې پټ راز شته چې هغه به ښکاره نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24136, 'Luke 8:18', 'Luke', 8, 18, '&nbsp;نو خبردار شئ چې تاسو څنګه اورئ ځکه چې د هر چا سره چې څۀ وى هغۀ له به نور هم ورکړے شى، او د چا سره چې څۀ نۀ وى هغۀ نه به هغه څۀ هم واخستلے شى چې ورسره وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24137, 'Luke 8:19', 'Luke', 8, 19, '&nbsp;بيا د عيسىٰ مور او وروڼه راغلل خو د ګڼې له کبله هغۀ ته ورونۀ رسېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24138, 'Luke 8:20', 'Luke', 8, 20, '&nbsp;چا هغۀ ته ووئيل چې، ”ستا مور او وروڼه بهر ولاړ دى، هغوئ تا سره مِلاوېدل غواړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24139, 'Luke 8:21', 'Luke', 8, 21, '&nbsp;هغۀ جواب ورکړو، ”زما مور او زما وروڼه هغه څوک دى چې د خُدائ پاک کلام اورى او عمل پرې کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24140, 'Luke 8:22', 'Luke', 8, 22, '&nbsp;يوه ورځ عيسىٰ د خپلو مريدانو سره په کشتۍ کښې سور شو او ورته يې وفرمائيل، ”راځئ چې د درياب پورې غاړې ته لاړ شُو.“ نو هغوئ روان شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24141, 'Luke 8:23', 'Luke', 8, 23, '&nbsp;او کله چې هغوئ په کِشتۍ کښې روان وُو، نو هغه اودۀ شو. خو په درياب کښې يو زورَور طوفان راغلو، او کِشتۍ د اوبو نه په ډکېدو شوه او هغوئ په سخته خطره کښې وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24142, 'Luke 8:24', 'Luke', 8, 24, '&nbsp;مريدان هغۀ له ورغلل او په چغو يې رابېدار کړو، ”مالِکه، مالِکه، مونږ ډوبيږو.“ هغه بېدار شو او سيلۍ او د اوبو چپې يې ورټلې. طوفان ودرېدو نو په هغه ساعت قلاره قلارى شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24143, 'Luke 8:25', 'Luke', 8, 25, '&nbsp;هغۀ ترې تپوس وکړو، ”ستاسو ايمان چرته دے؟“ هغوئ په يره او حېرانتيا يو بل ته ووئيل چې، ”دا لا څۀ قِسم سړے دے چې هوا او چپو له حکم ورکوى او هغوئ يې حکم منى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24144, 'Luke 8:26', 'Luke', 8, 26, '&nbsp;بيا عيسىٰ د خپلو مريدانو سره د ګِراسينيانو علاقې ته ورسېدلو کوم چې د ګليل په بله غاړه وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24145, 'Luke 8:27', 'Luke', 8, 27, '&nbsp;څنګه چې عيسىٰ وچې ته راکوز شو نو يو سړے يې وليدو چې پيريانو نيولے وو او د ډېر وخت نه يې نۀ خو جامې اغوستې وې او نۀ کور کښې اوسېدلے وو خو په قبرستان کښې دېره وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24146, 'Luke 8:28', 'Luke', 8, 28, '&nbsp;کله چې هغۀ عيسىٰ وليدلو نو چغې يې کړې او سجده يې ورته وکړه او دا چغې يې وهلې، ”اے عيسىٰ، د خُدائ پاک زويه، تۀ زما نه څۀ غواړې؟ د خُدائ تعالىٰ دپاره ما مۀ په عذابوه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24147, 'Luke 8:29', 'Luke', 8, 29, '&nbsp;ځکه چې عيسىٰ پيريانو ته حکم کړے وو چې دې سړى نه راوځئ. ډېر ځله يې هغه نيولے وو او د حفاظت د کبله به په زنځيرونو کښې وتړلے شو او زولنۍ به ورواچولے شوې خو هر ځل به هغۀ ځان خلاصولو او پيريانو به هغه بيابان ته بوتلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24148, 'Luke 8:30', 'Luke', 8, 30, '&nbsp;بيا عيسىٰ د هغۀ نه تپوس وکړو چې، ”نوم دې څۀ دے؟“ هغۀ ووئيل چې، ”زما نوم لښکر دے،“ ځکه چې هغه ډېرو پيريانو نيولے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24149, 'Luke 8:31', 'Luke', 8, 31, '&nbsp;هغوئ مِنت زارى ورته وکړه چې دا حکم مۀ راکوه چې تاترين ته وغورزېږئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24150, 'Luke 8:32', 'Luke', 8, 32, '&nbsp;نو هلته د غرۀ په خوا کښې د خنزيرانو يوه لويه رمه څرېده او پيريانو مِنت زارى ورته وکړه چې، ”مونږ له اجازت راکړه چې په دوئ کښې ورننوځو.“ نو هغۀ هغوئ له اجازت ورکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24151, 'Luke 8:33', 'Luke', 8, 33, '&nbsp;بيا پيريان د سړى نه راووتل او په خنزيرانو کښې ورننوتل او ټوله رمه په منډه شوه او د کمر نه ښکته درياب ته پرېوته او ډوبه شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24152, 'Luke 8:34', 'Luke', 8, 34, '&nbsp;د خنزيرانو ساتونکو چې دا وليدل نو وتښتېدل. هغوئ ښار او بانډو ته دا خبر ورسولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24153, 'Luke 8:35', 'Luke', 8, 35, '&nbsp;او خلق د دې تماشې دپاره بهر راووتل. کله چې هغوئ عيسىٰ له راغلل هغه سړے چې پيريان ترې تللى وُو يې وليدو چې جامې يې اغوستې وې او سم دم د عيسىٰ په پښو کښې ناست وو او هغوئ ويرېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24154, 'Luke 8:36', 'Luke', 8, 36, '&nbsp;کومو خلقو چې دا واقعه ليدلې وه هغوئ نورو ته ووئيل چې دا پيريانو نيولے سړے څنګه روغ شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24155, 'Luke 8:37', 'Luke', 8, 37, '&nbsp;نو د ګِراسينيانو د مُلک ټولو خلقو عيسىٰ ته مِنت زارى وکړه چې د دې علاقې نه لاړ شه. ځکه چې هغوئ ډېر يرې اخستى وُو. نو هغه کشتۍ ته وختلو او واپس لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24156, 'Luke 8:38', 'Luke', 8, 38, '&nbsp;د کوم سړى نه چې پيريان پاڅېدلى وُو هغۀ ورته خواست وکړو چې ورسره ملګرے شى. خو عيسىٰ هغه رُخصت کړو او ورته يې وفرمائيل چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24157, 'Luke 8:39', 'Luke', 8, 39, '&nbsp;”خپل کور ته واپس لاړ شه او هغه هر څۀ بيان کړه چې خُدائ پاک ستا دپاره وکړل.“ هغه لاړو په ښار کښې هرې خوا ته وګرځېدو او چې عيسىٰ د هغۀ دپاره څۀ کړى وُو هغه يې خلقو ته بيان کړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24158, 'Luke 8:40', 'Luke', 8, 40, '&nbsp;کله چې عيسىٰ راواپس شو نو خلقو ورته هرکلے ووې ځکه چې هغوئ ټول ورته په اِنتظار وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24159, 'Luke 8:41', 'Luke', 8, 41, '&nbsp;بيا يائير نومې يو سړے راغلو چې د عبادتخانې يو مشر وو. هغه د عيسىٰ په پښو پرېوتو او مِنت زارى يې ورته وکړه چې، ”ما سره کور ته لاړ شه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24160, 'Luke 8:42', 'Luke', 8, 42, '&nbsp;ځکه چې د هغۀ د دولسو کالو يک يو لور وه چې مرګى حال وه. کله چې عيسىٰ ورسره لاړو نو د خلقو په ګڼه کښې راګېر شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24161, 'Luke 8:43', 'Luke', 8, 43, '&nbsp;په هغوئ کښې يوه ښځه وه چې د دولسو کالو راسې يې وينه بهېدله او هيچا يې علاج نۀ شو کولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24162, 'Luke 8:44', 'Luke', 8, 44, '&nbsp;هغه د شا د طرفه راغله او د هغۀ د جامو لمن له يې لاس وروړو او سمدستى يې وينه ودرېده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24163, 'Luke 8:45', 'Luke', 8, 45, '&nbsp;عيسىٰ وفرمائيل، ”دا چا ما له لاس راوړو؟“ ټول منکر شول او پطروس ووئيل، ”مالِکه، ګڼه درباندې راټوله ده او خلق درته راجُختيږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24164, 'Luke 8:46', 'Luke', 8, 46, '&nbsp;خو عيسىٰ وفرمائيل چې، ”چا خو ما له لاس راوړو ځکه چې زۀ پوهه شوم چې يو طاقت ما نه بهر شو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24165, 'Luke 8:47', 'Luke', 8, 47, '&nbsp;کله چې ښځه پوهه شوه چې هغه پټېدے نۀ شى، نو په رپېدو سره راغله او د هغۀ په پښو کښې پرېوتله او د ټولو خلقو په وړاندې يې د دې اِقرار وکړو چې هغې ولې هغۀ له لاس وروړو او څنګه هغه سمدستى جوړه شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
