(24169, 'Luke 8:51', 'Luke', 8, 51, '&nbsp;کله چې هغه کور ته ورسېدو هغۀ د پطروس، يوحنا، يعقوب او د جينۍ د مور پلار نه علاوه ځان سره نور څوک ننوتلو ته پرې نۀ ښودل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
