(24173, 'Luke 8:55', 'Luke', 8, 55, '&nbsp;د هغې روح واپس راغلو، هغه سمدستى پاڅېده بيا هغۀ هغوئ ته وفرمائيل چې هغې ته د خوړلو څۀ ورکړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
