(24185, 'Luke 9:11', 'Luke', 9, 11, '&nbsp;خو خلق خبر شول او ورپسې لاړل. هغۀ خلقو ته هرکلے ووئيلو او هغوئ ته يې د خُدائ پاک د بادشاهۍ په حقله خبرې وکړې او چا ته چې د علاج ضرورت وو، هغوئ له يې شفا ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24186, 'Luke 9:12', 'Luke', 9, 12, '&nbsp;کله چې ماښام شو نو هغه دولس مريدان هغۀ له ورغلل او ورته يې ووئيل، ”دا خلق رُخصت کړه چې خوا او شا کلو او بانډو ته لاړ شى او ځان له د شپې تېرولو او د خوراک بندوبست وکړى ځکه چې مونږ دلته په خوشى بيابان کښې يُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24187, 'Luke 9:13', 'Luke', 9, 13, '&nbsp;خو عيسىٰ جواب ورکړو چې، ”تاسو د ځانه دوئ ته د خوراک څۀ ورکړئ چې وې خورى.“ نو هغوئ ووئيل چې، ”مونږ سره خو پينځۀ روټۍ او دوه کبان دى، نور هيڅ نشته، ترڅو چې مونږ په خپله لاړ نۀ شُو او د دوئ دپاره د خوراک څښاک بندوبست ونۀ کړُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24188, 'Luke 9:14', 'Luke', 9, 14, '&nbsp;دا خوا او شا پينځۀ زره سړى وُو. هغۀ خپلو مريدانو ته وفرمائيل چې، ”د دوئ نه د پنځوسو پنځوسو کسانو پېنډې جوړې کړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24189, 'Luke 9:15', 'Luke', 9, 15, '&nbsp;هغوئ هم داسې وکړل او ټول يې کښېنول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24190, 'Luke 9:16', 'Luke', 9, 16, '&nbsp;بيا عيسىٰ هغه پينځۀ روټۍ او دوه کبان واخستل او آسمان ته يې پاس وکتل، برکت يې ورکړو، ماتې يې کړې او مريدانو له يې ورکړې چې په خلقو يې تقسيم کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24191, 'Luke 9:17', 'Luke', 9, 17, '&nbsp;هغوئ ټولو ښۀ په مړه ګېډه خوراک وکړو او کومې پاتې ټوکړې چې راټولې کړے شوې نو دولس ټوکرۍ ترې ډکې شوې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24192, 'Luke 9:18', 'Luke', 9, 18, '&nbsp;يوه ورځ چې عيسىٰ يواځې دُعا کوله او د هغۀ مريدان هم حاضر وُو نو هغۀ د هغوئ نه تپوس وکړو چې، ”خلق څۀ وائى چې زۀ څوک يم؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24193, 'Luke 9:19', 'Luke', 9, 19, '&nbsp;هغوئ جواب ورکړو، ”ځينې وائى چې بپتسمه ورکوونکے يحيىٰ دے، نور دې الياس ګڼى، او ځينې وائى چې د پخوانو نبيانو نه يو بيا راژوندے شوے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24194, 'Luke 9:20', 'Luke', 9, 20, '&nbsp;نو هغۀ ورته وفرمائيل چې، ”تاسو څۀ وايئ چې زۀ څوک يم؟“ پطروس جواب ورکړو، ”تۀ د خُدائ پاک مسيح يې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24195, 'Luke 9:21', 'Luke', 9, 21, '&nbsp;بيا هغۀ هغوئ په سختۍ سره منع کړل او حکم يې ورکړو چې، ”هيچا ته مۀ وايئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24196, 'Luke 9:22', 'Luke', 9, 22, '&nbsp;او هغۀ وفرمائيل چې، ”اِبن آدم به خامخا ډيرې سختۍ وزغمى او مشران، مشران اِمامان او د شرعې عالمان به يې رد کړى، او هغه به ووژلے شى، او په درېمه ورځ به راژوندے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24197, 'Luke 9:23', 'Luke', 9, 23, '&nbsp;بيا هغۀ هغوئ ټولو ته وفرمائيل، ”کۀ څوک زما مريدان جوړېدل غواړى، هغه دې د خپل ځان نه منکر شى، او هره ورځ دې خپله سولۍ راواخلى او ما پسې دې راځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24198, 'Luke 9:24', 'Luke', 9, 24, '&nbsp;څوک چې خپل ځان ساتل غواړى هغه به يې بائيلى، خو څوک چې زما د خاطره خپل ژوند بائيلى، نو هغه به يې بچ کړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24199, 'Luke 9:25', 'Luke', 9, 25, '&nbsp;کۀ څوک د خپل ابدى ژوند په بدله کښې ټوله دُنيا ومومى نو هغۀ ځان له څۀ فائده ورکړه؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24200, 'Luke 9:26', 'Luke', 9, 26, '&nbsp;څوک چې په ما او زما په کلام شرميږى نو اِبن آدم به د هغوئ نه وشرميږى، کله چې هغه په خپل جلال او د پلار او د پاکو فرښتو جلال سره راشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');